internal sealed class UpdateHttpResult {internal int Status;internal string ETag;internal byte[] Bytes;}
// WinHTTP negotiates TLS 1.2 on Windows 7 independently of the installed CLR.
// Options are per-session: no registry, global .NET TLS or certificate changes.
internal static class UpdateHttp {
