 static void Check(bool ok){if(!ok)throw new Win32Exception(Marshal.GetLastWin32Error());}
 static IntPtr Handle(IntPtr handle){if(handle==IntPtr.Zero)throw new Win32Exception(Marshal.GetLastWin32Error());return handle;}
 static string Header(IntPtr request,string name){uint size=0;WinHttpQueryHeaders(request,65535,name,IntPtr.Zero,ref size,IntPtr.Zero);if(size==0)return "";if(size>16384)throw new InvalidDataException("Update header too large");IntPtr memory=Marshal.AllocHGlobal((int)size);try{Check(WinHttpQueryHeaders(request,65535,name,memory,ref size,IntPtr.Zero));return Marshal.PtrToStringUni(memory).TrimEnd('\0');}finally{Marshal.FreeHGlobal(memory);}}
 internal static UpdateHttpResult GetManifest(string url,string etag){if(url!=UpdateManifest.ManifestUrl)throw new InvalidDataException("Unexpected manifest URL");long bucket=(DateTime.UtcNow.Ticks-new DateTime(1970,1,1).Ticks)/TimeSpan.TicksPerSecond/30;url+="?poll="+bucket.ToString(System.Globalization.CultureInfo.InvariantCulture);using(MemoryStream output=new MemoryStream()){UpdateHttpResult result=Download(url,etag,output,196608,12000,false);result.Bytes=output.ToArray();return result;}}
 internal static void GetAsset(UpdateRelease release,string path){using(FileStream file=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.None)){UpdateHttpResult result=Download(release.Url,"",file,release.Size,180000,true);if(result.Status!=200||file.Length!=release.Size)throw new InvalidDataException("Incomplete update download");}}
 static UpdateHttpResult Download(string value,string etag,Stream output,long maximum,int deadline,bool asset){Uri uri=new Uri(value);Stopwatch clock=Stopwatch.StartNew();if(etag==null||etag.Length>512||etag.IndexOf('\r')>=0||etag.IndexOf('\n')>=0)etag="";for(int redirect=0;redirect<4;redirect++){if(asset?!UpdateManifest.IsDownloadHost(uri):uri.AbsoluteUri!=value)throw new InvalidDataException("Unexpected update host");IntPtr session=IntPtr.Zero,connect=IntPtr.Zero,request=IntPtr.Zero;try{session=Handle(WinHttpOpen("USBBridge/"+UpdateManifest.CurrentName,0,null,null,0));Check(WinHttpSetTimeouts(session,1500,2500,3000,3000));uint tls12=0x800;Check(WinHttpSetOption(session,84,ref tls12,4));connect=Handle(WinHttpConnect(session,uri.Host,(ushort)uri.Port,0));request=Handle(WinHttpOpenRequest(connect,"GET",uri.PathAndQuery,null,null,IntPtr.Zero,0x00800000));uint disableRedirects=2;Check(WinHttpSetOption(request,63,ref disableRedirects,4));string headers="Accept: application/json, application/octet-stream\r\nCache-Control: no-cache\r\n"+(etag.Length==0?"":"If-None-Match: "+etag+"\r\n");Check(WinHttpSendRequest(request,headers,(uint)headers.Length,IntPtr.Zero,0,0,IntPtr.Zero));Check(WinHttpReceiveResponse(request,IntPtr.Zero));if(clock.ElapsedMilliseconds>deadline)throw new IOException("Update request timed out");int status;{uint length=4;IntPtr number=Marshal.AllocHGlobal(4);try{Check(WinHttpQueryHeaders(request,19|0x20000000,null,number,ref length,IntPtr.Zero));status=Marshal.ReadInt32(number);}finally{Marshal.FreeHGlobal(number);}}if(status==301||status==302||status==303||status==307||status==308){string location=Header(request,"Location");Uri next;if(!Uri.TryCreate(uri,location,out next)||!asset||!UpdateManifest.IsDownloadHost(next))throw new InvalidDataException("Unsafe update redirect");uri=next;continue;}UpdateHttpResult result=new UpdateHttpResult{Status=status,ETag=Header(request,"ETag")};if(status==304&&!asset)return result;if(status!=200)throw new IOException("Update server HTTP "+status);string declared=Header(request,"Content-Length");long contentLength;if(declared.Length!=0&&(!long.TryParse(declared,out contentLength)||contentLength<0||contentLength>maximum))throw new InvalidDataException("Update body too large");byte[] buffer=new byte[32768];long total=0;while(true){if(clock.ElapsedMilliseconds>deadline)throw new IOException("Update request timed out");uint read;Check(WinHttpReadData(request,buffer,(uint)buffer.Length,out read));if(read==0)break;total+=read;if(total>maximum)throw new InvalidDataException("Update body too large");output.Write(buffer,0,(int)read);}return result;}finally{if(request!=IntPtr.Zero)WinHttpCloseHandle(request);if(connect!=IntPtr.Zero)WinHttpCloseHandle(connect);if(session!=IntPtr.Zero)WinHttpCloseHandle(session);}}throw new IOException("Too many update redirects");}
}
}
